import {dashboardMarkup,bindDashboard} from './dashboard.mjs';
import {activityTitle,entriesFor} from './catalog.mjs';
export const WELCOME_KEY='education-facilitation-guide:welcome';
export const welcomeStages=[['18m','18–23 meses','Un turno contigo'],['2y','24–35 meses','Imitar juntos'],['3y','3–5 años','Mirar y probar'],['5y','6–8 años','Explorar con ayuda'],['7y','9–12 años','Comparar ideas'],['12y','13–18 años','Preguntar con razones']];
export function decodeWelcome(raw){
 if(raw===null)return {ok:true,value:null};
 try{if(typeof raw!=='string'||raw.length>160)throw Error();const p=JSON.parse(raw);if(!p||Object.keys(p).sort().join(',')!=='role,stage,version'||p.version!==1||!['adult','student'].includes(p.role)||!welcomeStages.some(s=>s[0]===p.stage)||(p.role==='student'&&!['7y','12y'].includes(p.stage)))throw Error();return {ok:true,value:p};}catch{return {ok:false,value:null};}
}
const art=(kind='path')=>`<svg class="welcome-art" viewBox="0 0 320 180" aria-hidden="true"><rect x="4" y="4" width="312" height="172" rx="38" fill="#e9eedf"/><path d="M35 140 Q100 40 160 120 T290 55" fill="none" stroke="#9caa85" stroke-width="5" stroke-dasharray="8 10"/><circle cx="78" cy="104" r="30" fill="#215747"/><path d="M78 122 V85 M78 104 Q56 104 60 85 Q78 85 78 104 M78 96 Q97 96 95 78 Q78 79 78 96" fill="none" stroke="#fffdf5" stroke-width="3"/>${kind==='ball'?'<circle cx="205" cy="120" r="29" fill="#b45e40"/><path d="M180 108 Q205 135 230 108" fill="none" stroke="#fffdf5" stroke-width="3"/>':'<rect x="180" y="56" width="64" height="64" rx="14" fill="#e4bc69"/><path d="M195 90 L207 101 L229 76" fill="none" stroke="#354b36" stroke-width="5"/>'}<circle cx="264" cy="34" r="12" fill="#e4bc69"/></svg>`;
const stageArt=(id)=>{
 const scenes={
  '18m':['#f6e6cf','#aa5942','<circle cx="93" cy="92" r="27"/><circle cx="213" cy="112" r="23" fill="#d09a54"/><path d="M122 112 Q154 136 184 117" fill="none" stroke="#6d8469" stroke-width="7" stroke-linecap="round"/>'],
  '2y':['#e8edf3','#4c7182','<rect x="70" y="66" width="42" height="60" rx="12"/><circle cx="91" cy="57" r="22"/><path d="M157 122 Q183 82 220 118 L211 130 H165Z" fill="#d29c50"/><path d="M169 84 L210 83 L227 113 L193 121Z" fill="#7992a0"/>'],
  '3y':['#e9efdb','#4d765d','<circle cx="98" cy="101" r="25" fill="#dd9d47"/><path d="M96 77 Q99 54 117 54 Q116 75 96 77Z"/><rect x="165" y="85" width="58" height="44" rx="8"/><path d="M177 86 Q180 64 194 64 Q209 64 211 86" fill="none" stroke="#4d765d" stroke-width="7"/>'],
  '5y':['#efe9d7','#7b6847','<path d="M100 127 Q91 83 112 54 Q143 86 126 127Z"/><path d="M110 117 L126 83" fill="none" stroke="#f8f3e7" stroke-width="5"/><path d="M171 69 H222 V128 H171Z"/><path d="M196 69 V128 M180 85 H190 M202 85 H214" stroke="#f8f3e7" stroke-width="4"/>'],
  '7y':['#e6edf0','#416777','<rect x="66" y="58" width="70" height="75" rx="8"/><rect x="183" y="58" width="70" height="75" rx="8"/><path d="M81 111 L99 91 L117 102" fill="none" stroke="#416777" stroke-width="7"/><path d="M198 102 L216 81 L235 91" fill="none" stroke="#aa5942" stroke-width="7"/>'],
  '12y':['#eee9ed','#684e71','<path d="M77 63 Q119 53 158 66 V132 Q117 119 77 130Z"/><path d="M158 66 Q198 53 239 63 V130 Q199 119 158 132Z"/><path d="M94 84 H139 M94 98 H133 M178 84 H222 M178 98 H212" stroke="#684e71" stroke-width="5"/>']
 };
 const [bg,ink,shape]=scenes[id]||scenes['18m'];
 return `<svg class="welcome-stage-art" viewBox="0 0 320 180" aria-hidden="true"><rect x="4" y="4" width="312" height="172" rx="34" fill="${bg}"/><g fill="${ink}">${shape}</g><circle cx="265" cy="35" r="9" fill="${ink}" opacity=".25"/></svg>`;
};
const goalArt=a=>`<svg class="welcome-goal-art" viewBox="0 0 240 120" aria-hidden="true"><rect width="240" height="120" rx="24" fill="#e9eedf"/>${a.type==='guide'?'<circle cx="91" cy="67" r="34" fill="#bd654b"/><path d="M58 58 Q91 91 124 58" fill="none" stroke="#fffdf5" stroke-width="5"/><path d="M166 81 Q184 46 214 76" fill="none" stroke="#7c9370" stroke-width="8" stroke-linecap="round"/>':a.key.endsWith(':original')?'<rect x="40" y="61" width="39" height="39" rx="9" fill="#24604f"/><circle cx="142" cy="52" r="27" fill="#bd654b"/><path d="M173 99 L205 45 L234 99 Z" fill="#c19143"/>':a.id==='quantity'?'<path d="M30 70 Q58 54 84 70 L78 98 H37Z M108 70 Q136 54 162 70 L156 98 H115Z M182 70 Q210 54 236 70 L230 98 H189Z" fill="#729383"/><circle cx="56" cy="53" r="12" fill="#c19143"/><circle cx="134" cy="51" r="12" fill="#bd654b"/><circle cx="208" cy="53" r="12" fill="#24604f"/>':a.area==='Idiomas'||a.area==='Lenguaje'?'<path d="M34 22 H206 V78 H112 L82 101 V78 H34Z" fill="#215747"/><path d="M66 42 H172 M66 58 H147" stroke="#fffdf5" stroke-width="7"/>':a.area==='Pensamiento crítico'||a.area==='Filosofía'?'<path d="M38 22 H108 V98 H38Z M132 22 H202 V98 H132Z" fill="#fffdf7" stroke="#84977d" stroke-width="4"/><path d="M53 42 H92 M53 57 H87 M147 42 H185 M147 57 H178" stroke="#496d63" stroke-width="5"/><path d="M111 60 H129" stroke="#bd654b" stroke-width="6"/>':'<circle cx="75" cy="54" r="27" fill="#e4bc69" stroke="#215747" stroke-width="5"/><path d="M96 74 L125 100 M59 54 H91" stroke="#215747" stroke-width="7"/>'}</svg>`;
export function mountWelcome(root,{storage,getResume,openActivity,onHome}){
 let baseline=null,pref=null,message='',step=0,role='adult',band=null,demo=false,dashboardBand=undefined,resumeSignature='';
 const signature=()=>{const r=getResume();return r?r.key+':'+r.phase:'';};
 try{baseline=storage?.getItem(WELCOME_KEY)??null;const decoded=decodeWelcome(baseline);pref=decoded.value;if(!decoded.ok)message='No pudimos leer este inicio. Lo conservamos sin sustituirlo.';}catch{message='Puedes explorar sin guardar este inicio.';}
 if(pref){role=pref.role;band=pref.stage;}
 const library=document.querySelector('#all-proposals'),stageSection=document.querySelector('#etapas'),anchor=document.createComment('stage home');stageSection.before(anchor);
 const back=document.querySelector('#back-home');
 const setHome=()=>{document.body.classList.remove('guided-session','garden-focus');anchor.after(stageSection);back.hidden=true;library.open=false;onHome();document.body.classList.remove('garden-focus');step=0;draw();root.querySelector('h1')?.focus();};
 back.addEventListener('click',setHome);
 const launch=key=>{document.body.classList.add('guided-session');back.after(stageSection);back.hidden=false;openActivity(key);};
 const mutate=value=>{
  try{if(!storage)throw Error();const now=storage.getItem(WELCOME_KEY);if(now!==baseline||!decodeWelcome(now).ok){message='Este inicio cambió en otra pestaña o no se puede leer. Recarga antes de guardarlo; tus juegos se conservan.';return;}
   if(value===null)storage.removeItem(WELCOME_KEY);else storage.setItem(WELCOME_KEY,JSON.stringify(value));
   const expected=value===null?null:JSON.stringify(value);if(storage.getItem(WELCOME_KEY)!==expected)throw Error();baseline=expected;pref=value;message=value?'Inicio recordado en este navegador. No cambia tus juegos.':'Preferencias del inicio borradas. Tus juegos y Luma se conservan.';
  }catch{message='No se pudo guardar este inicio. Puedes seguir en esta sesión; tus juegos no se borran.';}
 };
 const bind=(id,fn)=>root.querySelector('#'+id)?.addEventListener('click',fn);
 const render=()=>{draw();root.querySelector('[tabindex="-1"]')?.focus();};
 function draw(){
  resumeSignature=signature();
  const resume=getResume(),info=welcomeStages.find(s=>s[0]===band),young=['18m','2y'].includes(band),adult=!['7y','12y'].includes(band)||role==='adult';
  let content='';
  if(step===0)content=`<div class="welcome-lead"><div><p class="eyebrow">A TU RITMO · CON ESPACIO PARA PARAR</p><h1 tabindex="-1">¿Qué exploramos hoy?</h1><p>Áreas, juegos y apoyo, a tu alcance. Elige una idea y avanza a tu ritmo.</p><div class="controls">${resume?`<button type="button" class="action primary" id="welcome-continue">Continuar · ${activityTitle(resume)}</button>`:''}<button type="button" class="action ${resume?'secondary':'primary'}" id="welcome-begin">${resume?'Elegir otra actividad':pref?'Elegir una actividad':'Encontrar por dónde empezar'}</button></div>${resume?`<p class="quiet">${welcomeStages.find(s=>s[0]===resume.stage)?.[1]||''} · ${resume.phase==='paused'?'En pausa':'En curso'}</p>`:''}</div>${art()}</div>`;
  if(step===1)content=`<p class="eyebrow">1 DE 3 · COMPAÑÍA</p><h1 tabindex="-1">¿Cómo vamos a explorar?</h1><div class="welcome-choices"><button type="button" class="welcome-choice" data-role="adult">${art('ball')}<strong>Un adulto con un niño o estudiante</strong><span>Yo acompaño, leo y ajusto la ayuda.</span></button><button type="button" class="welcome-choice" data-role="student">${art()}<strong>Soy estudiante</strong><span>Puedo leer por mi cuenta y pedir apoyo.</span></button></div>`;
  if(step===2)content=`<p class="eyebrow">2 DE 3 · UN PUNTO DE PARTIDA</p><h1 tabindex="-1">Elige una franja orientativa.</h1><p>No necesitamos tu fecha de nacimiento. Puedes cambiar después.</p><div class="welcome-bands">${welcomeStages.map(([id,label,note])=>`<button type="button" class="welcome-choice age-choice" data-band="${id}">${stageArt(id)}<strong>${label}</strong><span>${note}</span></button>`).join('')}</div>`;
  if(step===3){
   const entries=entriesFor(band).sort((a,b)=>Number(a.id==='words')-Number(b.id==='words')||Number(a.id==='quantity')-Number(b.id==='quantity')),primary=entries.slice(0,1),extra=entries.slice(1);
   const card=a=>`<button type="button" class="welcome-choice" data-welcome-route="${a.key}">${goalArt(a)}<span>${a.area}</span><strong>${activityTitle(a)}</strong>${a.age?`<span>${a.age}</span>`:''}<span>${a.type==='guide'?'Ver la guía del adulto':'Abrir esta actividad'} · disponible</span></button>`;
   content=`<p class="eyebrow">3 DE 3 · ${info[1]} · ${band==='3y'?'APOYO SEGÚN LA PROPUESTA':adult?'CON ADULTO':'CON APOYO SI LO NECESITAS'}</p><h1 tabindex="-1">${young?'Un momento juntos, fuera de la pantalla.':'¿Qué te apetece probar hoy?'}</h1>${young?`<div class="welcome-demo">${stageArt(band)}<div><p>${band==='18m'?'Adulto: una invitación breve con una pelota grande y blanda. El niño puede mirar, tocar o pasar.':'Adulto: saluda a un muñeco e invita a imitar o cambiar la historia.'}</p><button type="button" class="action secondary" id="welcome-demo">${demo?'Ocultar la guía':'Preparar el momento'}</button>${demo?`<div role="status" class="adult-layer"><p>${band==='18m'?'Prepara un espacio despejado y una pelota grande, blanda y adecuada. Hazla rodar suavemente una vez; espera sin pedir respuesta.':'Usa un muñeco y una tela grande adecuada, bajo supervisión. Saluda, cubre y descubre, e invita a imitar o cambiar la historia.'}</p><p>La compañía adulta se mantiene todo el tiempo. Sin piezas pequeñas, lectura, cuentas ni tarea en pantalla. Sigue el interés del niño y para si lo desea. Aparta la pantalla para la actividad física.</p></div>`:''}</div></div>`:`<p>${band==='3y'?'Una propuesta visual para probar; el apoyo está disponible.':'Empieza por una propuesta. Puedes cambiarla o parar cuando quieras.'}</p><ol class="welcome-map" aria-label="Tu próximo paso"><li>Elige</li><li>Prueba con ayuda</li><li>Llévalo fuera de pantalla</li></ol>`}<div class="welcome-choices">${primary.map(card).join('')}</div>${extra.length?`<details class="welcome-more"><summary>Ver otras propuestas de esta franja (${extra.length})</summary><div class="welcome-choices">${extra.map(card).join('')}</div></details>`:''}<details class="welcome-family"><summary>${young?'Guía completa para la persona adulta':'Ayuda, pausa y salida'}</summary><p>${young?'No hay juego autónomo en pantalla ni pasos que el pequeño deba completar. Sigue su iniciativa; puedes parar ahora.':'Ofrece una pista y espera. Se puede señalar, pedir ayuda, cambiar de propuesta o descansar. No hace falta acertar para que la conversación tenga valor.'}</p><p>Puedes cambiar de franja o volver al inicio en cualquier momento. No necesitas completar actividades para elegir otra edad. Estas sugerencias organizan la interfaz; no evalúan capacidades ni certifican resultados.</p></details><div class="controls"><button type="button" class="action secondary" id="welcome-remember">Recordar este inicio</button><button type="button" class="action secondary" id="welcome-band">Cambiar franja</button></div><p class="quiet">Recordar guarda solo franja y tipo de acompañamiento en este navegador compartido.</p>`;
  }
  root.innerHTML=content+(step===0?dashboardMarkup(dashboardBand??band??resume?.stage??''):'')+`<div class="welcome-tools">${step>0?'<button type="button" class="action secondary" id="welcome-back">Atrás</button>':''}<button type="button" class="action secondary" id="welcome-skip">${step?'Omitir guía · ver todas las áreas':'Explorar todas las áreas'}</button>${pref?'<button type="button" class="action secondary" id="welcome-reset">Olvidar preferencias del inicio</button>':''}</div><p id="welcome-status" role="status" aria-live="polite">${message}</p>`;
  if(step===0)bindDashboard(root,{band:dashboardBand??band??resume?.stage??'',onBand:value=>{dashboardBand=value;if(value){band=value;if(!['7y','12y'].includes(band))role='adult';message=pref&&pref.stage!==band?'Franja cambiada solo para esta sesión. Tu inicio recordado no cambia.':'';}draw();root.querySelector('#dashboard-band').focus();},launch,openDestination:target=>{
   if(target==='progress'){if(document.querySelector('#progress-options').getAttribute('aria-expanded')!=='true')document.querySelector('#progress-options').click();document.querySelector('#progress-options').focus();document.querySelector('#local-progress').scrollIntoView?.({block:'start'});return;}
   showCatalog();let destination;
   if(target==='companion'){const dock=document.querySelector('#activity-companion');if(dock)dock.open=true;destination=document.querySelector('#companion-title');}
   else if(target==='family')destination=document.querySelector('#principios h2');
   else destination=document.querySelector('#'+target+' h3');
   if(destination){destination.tabIndex=-1;destination.focus();destination.scrollIntoView?.({block:'start'});}
  }});
  bind('welcome-begin',()=>{step=band?3:1;render();});bind('welcome-continue',()=>{const candidate=getResume();if(candidate)launch(candidate.key);else render();});
  root.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;band=null;step=2;demo=false;message='';render();});
  root.querySelectorAll('[data-band]').forEach(b=>b.onclick=()=>{band=b.dataset.band;if(!['7y','12y'].includes(band))role='adult';step=3;demo=false;message=pref&&(pref.stage!==band||pref.role!==role)?'Cambio solo en esta sesión. Pulsa «Recordar este inicio» si quieres conservarlo.':'';render();});
  root.querySelectorAll('[data-welcome-route]').forEach(b=>b.onclick=()=>launch(b.dataset.welcomeRoute));
  bind('welcome-demo',()=>{demo=!demo;draw();root.querySelector('#welcome-demo').focus();});
  bind('welcome-back',()=>{step=Math.max(0,step-1);demo=false;render();});bind('welcome-band',()=>{step=2;demo=false;render();});
  bind('welcome-remember',()=>{mutate({version:1,role,stage:band});render();});
  bind('welcome-reset',()=>{mutate(null);if(pref===null){band=null;role='adult';step=0;}render();});
  bind('welcome-skip',()=>{library.open=true;library.querySelector('summary').focus();library.scrollIntoView?.({block:'start'});});
 }
 const showCatalog=()=>{document.body.classList.remove('guided-session','garden-focus');anchor.after(stageSection);back.hidden=true;library.open=true;draw();};
 document.addEventListener('click',event=>{const trigger=event.target.closest('#garden-library,#paused-catalog,#finished-catalog');if(document.body.classList.contains('guided-session')&&trigger){event.preventDefault();showCatalog();const target=trigger.id==='finished-catalog'?document.querySelector('#stage-buttons [aria-pressed="true"]'):document.querySelector('#stage-title');target?.focus();stageSection.scrollIntoView?.({block:'start'});}});
 document.querySelectorAll('a[href="#principios"],.explore-nav a').forEach(a=>a.addEventListener('click',()=>{if(document.body.classList.contains('guided-session'))showCatalog();library.open=true;}));
 document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();setHome();});
 draw();
 return {launch,refresh:()=>{if(step===0&&!document.body.classList.contains('guided-session')&&resumeSignature!==signature())draw();}};
}
